// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    Receiver bankReceiver;

    function setUp() public {
        bankReceiver = new Receiver();
        vm.prank(address(bankReceiver)); // bank must be able to receive the 1-wei fee
        c = new EtherLotto();
    }

    function testFuzz_property(uint256 ts, address player) public {
        vm.assume(player.code.length == 0);
        vm.assume(player != address(0));

        vm.warp(ts);
        vm.roll(ts % 1000 + 1); // vary block difficulty via prevrandao/difficulty

        uint256 bankBalBefore = c.bank().balance;
        uint256 potBefore = c.pot();

        vm.deal(player, 10);
        vm.prank(player);
        c.play{value: 10}();

        // Rule: whenever a winning play occurred (the bank received its FEE_AMOUNT of 1 wei),
        // the pot must have been reset to 0. The reference always resets pot on a win;
        // the mutant leaves the accumulated pot (potBefore + 10) in place.
        assertTrue(c.bank().balance != bankBalBefore + 1 || c.pot() == 0);
    }
}

contract Receiver {
    receive() external payable {}
}
